            const line = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0x333333 }));
            platform.add(line);
            group.add(platform);

            // 3. Middle Tier
            const midTierGeo = new THREE.BoxGeometry(8, 1, 8);
